U_normal_solution:
#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    int n;
    cin >> n;
    string trophies;
    cin >> trophies;

    vector<int> gold_lengths;
    int current_length = 0;
    int total_golden = 0;

    // Calculate lengths of all golden segments and total number of golden trophies
    for (int i = 0; i < n; ++i) {
        if (trophies[i] == 'G') {
            current_length++;
            total_golden++;
        } else {
            if (current_length > 0) {
                gold_lengths.push_back(current_length);
                current_length = 0;
            }
        }
    }
    if (current_length > 0) {
        gold_lengths.push_back(current_length);
    }

    // If all are golden
    if (total_golden == n) {
        cout << n << endl;
        return 0;
    }

    int max_beauty = 0;

    for (int i = 0; i < gold_lengths.size(); ++i) {
        // Check the beauty without any swap
        max_beauty = max(max_beauty, gold_lengths[i]);

        // Check the beauty if we swap around a single silver
        if (i < gold_lengths.size() - 1 && gold_lengths[i] + gold_lengths[i + 1] + 1 <= total_golden) {
            max_beauty = max(max_beauty, gold_lengths[i] + gold_lengths[i + 1] + 1);
        }
    }

    // Check if we can add one more golden by swapping one silver with a golden from elsewhere
    if (gold_lengths.size() > 1) {
        max_beauty = min(max_beauty + 1, total_golden);
    }

    cout << max_beauty << endl;

    return 0;
}

