#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    int n;
    cin >> n;
    vector<char> trophies(n);
    for (int i = 0; i < n; i++) {
        cin >> trophies[i];
    }

    int maxBeauty = 0;
    int currentBeauty = 0;
    int goldenCount = 0;

    for (int i = 0; i < n; i++) {
        if (trophies[i] == 'G') {
            currentBeauty++;
            goldenCount++;
        } else {
            maxBeauty = max(maxBeauty, currentBeauty);
            currentBeauty = 0;
        }
    }

    maxBeauty = max(maxBeauty, currentBeauty);

    for (int i = 0; i < n; i++) {
        if (trophies[i] == 'S') {
            int left = i - 1, right = i + 1;
            int currentLength = 0;
            while (left >= 0 && trophies[left] == 'G') {
                left--;
                currentLength++;
            }
            while (right < n && trophies[right] == 'G') {
                right++;
                currentLength++;
            }
            maxBeauty = max(maxBeauty, min(currentLength, goldenCount));
        }
    }

    cout << maxBeauty << endl;

    return 0;
}

