#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    int n;
    cin >> n;
    string trophies;
    cin >> trophies;

    vector<int> gold_lengths;
    int current_length = 0;
    int total_golden = 0;

    // Calculate lengths of all golden segments and total number of golden trophies
    for (int i = 0; i < n; ++i) {
        if (trophies[i] == 'G') {
            current_length++;
            total_golden++;
        } else {
            if (current_length > 0) {
                gold_lengths.push_back(current_length);
                current_length = 0;
            }
        }
    }
    if (current_length > 0) {
        gold_lengths.push_back(current_length);
    }

    // If all are golden
    if (total_golden == n) {
        cout << n << endl;
        return 0;
